import subprocess, os, tempfile
def run(args, input_data=None, env_extra=None):
    env=os.environ.copy()
    env["PAGER"]="cat"
    for k in list(env.keys()):
        if k.startswith("BAT_"): del env[k]
    if env_extra: env.update(env_extra)
    return subprocess.run(["./executable"]+args, input=input_data, capture_output=True, env=env)
import tempfile, os
# binary detection: docs say binary no-printing default? Let's test different binaries
for content in [b"\x00\x01\x02", b"hello\x00world\n", b"\xff\xfe\xfd", b"plain text\n"]:
    tf=tempfile.NamedTemporaryFile(delete=False); tf.write(content); tf.close()
    for args in [[tf.name], ["--binary=no-printing", tf.name], ["--binary=as-text", tf.name]]:
        r=run(args)
        print(f"content {content!r} args {args[0] if len(args)>1 else 'default'} => rc {r.returncode} out {r.stdout!r} err {r.stderr!r}")
    os.unlink(tf.name)
    print("---")
PY"}

