import subprocess, os, tempfile
def run(args, input_data=None, env_extra=None):
    env=os.environ.copy(); env["PAGER"]="cat"
    for k in list(env.keys()):
        if k.startswith("BAT_"): del env[k]
    if env_extra:
        for k,v in env_extra.items():
            if v is None: env.pop(k,None)
            else: env[k]=v
    return subprocess.run(["./executable"]+args, input=input_data, capture_output=True, env=env)
import tempfile, os
tf=tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.txt'); tf.write("hi\n"); tf.close()
for ct in ["truecolor","24bit","yes","1", "", "256"]:
    r=run(["--color=always","--style=plain", tf.name], env_extra={"COLORTERM":ct})
    print(f"COLORTERM={ct!r} => {repr(r.stdout)}")
# test BAT_THEME with truecolor?
r=run(["--color=always","--style=plain","--theme=Dracula", tf.name], env_extra={"COLORTERM":"truecolor"})
print("dracula truecolor", repr(r.stdout[:200]))
r=run(["--color=always","--style=plain","--theme=Dracula", tf.name])
print("dracula 256", repr(r.stdout[:200]))
os.unlink(tf.name)
PY"}

