import subprocess, os, tempfile
def run_orig(args, input_data=None):
    env=os.environ.copy(); env["PAGER"]="cat"
    for k in list(env.keys()):
        if k.startswith("BAT_"): del env[k]
    return subprocess.run(["./executable"]+args, input=input_data, capture_output=True, env=env)
def run_new(args, input_data=None):
    env=os.environ.copy(); env["PAGER"]="cat"
    for k in list(env.keys()):
        if k.startswith("BAT_"): del env[k]
    return subprocess.run(["python3","/workspace/main.py"]+args, input=input_data, capture_output=True, env=env)

import tempfile, os
tf=tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.txt'); tf.write("hello\nworld\n"); tf.close()
for args in [[tf.name], ["-n", tf.name], ["--decorations=always", tf.name], ["--decorations=always","--style=numbers", tf.name], ["-A", tf.name]]:
    r1=run_orig(args)
    r2=run_new(args)
    ok = (r1.stdout==r2.stdout and r1.stderr==r2.stderr and r1.returncode==r2.returncode)
    print(f"{args} {'OK' if ok else 'FAIL'}")
    if not ok:
        print(" orig out",repr(r1.stdout[:500]))
        print(" new  out",repr(r2.stdout[:500]))
        print(" orig err",repr(r1.stderr[:500]))
        print(" new  err",repr(r2.stderr[:500]))
        print(" rc",r1.returncode, r2.returncode)
os.unlink(tf.name)
