import subprocess, os, tempfile
def run_orig(args, input_data=None):
    env=os.environ.copy(); env["PAGER"]="cat"
    for k in list(env.keys()):
        if k.startswith("BAT_"): del env[k]
    return subprocess.run(["./executable"]+args, input=input_data, capture_output=True, env=env)
def run_new(args, input_data=None):
    env=os.environ.copy(); env["PAGER"]="cat"
    for k in list(env.keys()):
        if k.startswith("BAT_"): del env[k]
    return subprocess.run(["python3","/workspace/main.py"]+args, input=input_data, capture_output=True, env=env)
import tempfile, os
f1=tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.txt'); f1.write("file1 line1\nfile1 line2\n"); f1.close()
f2=tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.txt'); f2.write("file2 line1\n"); f2.close()
for a in [["--decorations=always","--style=header", f1.name, f2.name]]:
    r1=run_orig(a)
    r2=run_new(a)
    print("OK" if r1.stdout==r2.stdout else "FAIL")
    print(repr(r1.stdout[:200]), repr(r2.stdout[:200]))
os.unlink(f1.name); os.unlink(f2.name)
PY"}

